const scenarios = {
    "Variables & Data Types": {
        hints: ["Normalize external values at the boundary and keep the original value available when needed.", "Check both the JavaScript type and the permitted numeric range; Number.isFinite rejects NaN and infinities."],
        items: [
            ["Easy", "Normalize a profile form", "Implement normalizeProfileInput for a form whose age arrives as text and whose newsletter checkbox arrives as a boolean. Trim the name, convert age to a number, and preserve the checkbox as a boolean; reject blank names and non-finite or negative ages.", "normalizeProfileInput({name:' Ada ',age:'36',newsletter:true}) returns {name:'Ada',age:36,newsletter:true}.", "An age of '' or 'NaN' must be rejected rather than becoming a usable number.", "function normalizeProfileInput(input) { const name = String(input.name ?? '').trim(); const age = Number(input.age); if (!name || !Number.isFinite(age) || age < 0 || typeof input.newsletter !== 'boolean') throw new TypeError('Invalid profile'); return { name, age, newsletter: input.newsletter }; }", "Treat form values according to their actual runtime types, not the labels shown in the form.", "Convert age once, then validate the converted number before returning the normalized object."],
            ["Easy", "Format a price without coercion surprises", "Write formatPrice that accepts a finite non-negative number and returns a string with exactly two decimal places. The caller may pass 12, 12.5, or 12.345; reject strings instead of silently coercing them.", "formatPrice(12.5) returns '12.50'.", "formatPrice('12.5') and formatPrice(Infinity) throw a TypeError.", "function formatPrice(value) { if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) throw new TypeError('Price must be a finite non-negative number'); return value.toFixed(2); }", "Do not confuse a numeric-looking string with a number when the function contract requires a number.", "Validate type, finiteness, and sign before calling toFixed."],
            ["Medium", "Reconcile API quantities safely", "An inventory API may return quantity as a number or a non-empty numeric string. Implement parseQuantity to accept integer values from 0 through 100000 and reject decimals, empty strings, booleans, null, and out-of-range values.", "parseQuantity('0') returns 0 and parseQuantity(12) returns 12.", "parseQuantity('12.5'), parseQuantity(''), and parseQuantity(true) are invalid.", "function parseQuantity(value) { if (typeof value !== 'number' && !(typeof value === 'string' && value.trim() !== '')) throw new TypeError('Invalid quantity'); const number = Number(value); if (!Number.isSafeInteger(number) || number < 0 || number > 100000) throw new RangeError('Quantity out of range'); return number; }", "Guard the accepted input types before conversion because Number(true) and Number('') produce numbers.", "After conversion, use Number.isSafeInteger and enforce both ends of the domain."],
            ["Medium", "Build a typed checkout summary", "Create checkoutSummary with itemCount, subtotal, and giftWrap. Validate itemCount as a non-negative safe integer, subtotal as a finite non-negative number, and giftWrap as a boolean; return a new object with a formatted subtotal string and do not mutate the input.", "{itemCount:2,subtotal:19.9,giftWrap:false} becomes {itemCount:2,subtotal:'19.90',giftWrap:false}.", "A NaN subtotal or string 'false' for giftWrap must be rejected.", "function checkoutSummary(input) { if (!Number.isSafeInteger(input.itemCount) || input.itemCount < 0 || typeof input.subtotal !== 'number' || !Number.isFinite(input.subtotal) || input.subtotal < 0 || typeof input.giftWrap !== 'boolean') throw new TypeError('Invalid checkout data'); return { itemCount: input.itemCount, subtotal: input.subtotal.toFixed(2), giftWrap: input.giftWrap }; }", "Write down the accepted runtime type for every field before formatting anything.", "Use a fresh return object so presentation formatting cannot alter the source payload."],
            ["Hard", "Validate a mixed-value analytics event", "Implement normalizeSignupEvent for untrusted event data containing a user ID, timestamp, and optional campaign. Require a trimmed non-empty string ID, a valid Date or ISO timestamp that parses to a finite time, and a string campaign when present; return a canonical ISO timestamp and omit campaign when it is blank.", "A valid Date plus campaign ' spring ' becomes an ISO string and campaign 'spring'.", "Reject an invalid Date and a numeric user ID; do not serialize either as plausible data.", "function normalizeSignupEvent(event) { if (typeof event.userId !== 'string' || !event.userId.trim()) throw new TypeError('Invalid userId'); const date = event.timestamp instanceof Date ? event.timestamp : new Date(event.timestamp); if (!Number.isFinite(date.getTime())) throw new TypeError('Invalid timestamp'); if (event.campaign != null && typeof event.campaign !== 'string') throw new TypeError('Invalid campaign'); const campaign = event.campaign?.trim(); return { userId: event.userId.trim(), timestamp: date.toISOString(), ...(campaign ? { campaign } : {}) }; }", "Validate each value before relying on implicit string or date conversion.", "Canonicalize only after the input has passed its type and validity checks."],
            ["Hard", "Design a money-safe invoice input contract", "Implement invoiceTotal that accepts line items with integer quantity and integer cents, validates every item, and returns total cents plus a display string. Avoid binary floating-point arithmetic for money and reject unsafe totals.", "[{quantity:3,unitCents:199}] produces totalCents 597 and display '$5.97'.", "An empty list totals zero; a fractional quantity or unsafe integer must fail.", "function invoiceTotal(items) { if (!Array.isArray(items)) throw new TypeError('Items must be an array'); let totalCents = 0; for (const item of items) { if (!Number.isSafeInteger(item.quantity) || item.quantity < 0 || !Number.isSafeInteger(item.unitCents) || item.unitCents < 0) throw new TypeError('Invalid line item'); const line = item.quantity * item.unitCents; if (!Number.isSafeInteger(line) || !Number.isSafeInteger(totalCents + line)) throw new RangeError('Total exceeds safe integer range'); totalCents += line; } return { totalCents, display: `$${(totalCents / 100).toFixed(2)}` }; }", "Represent currency as integer minor units and validate both multiplication and accumulation.", "Keep the exact total in cents; convert to a decimal string only for display."],
        ]
    },
    Conditions: {
        hints: ["Translate the business rule into mutually exclusive branches before writing the conditions.", "Handle invalid values first, then test the inclusive or exclusive boundaries explicitly."],
        items: [
            ["Easy", "Classify a delivery window", "Write deliveryWindow(minutes) for a non-negative finite number of minutes: 'soon' below 30, 'today' from 30 through 240 inclusive, and 'scheduled' above 240. Return 'invalid' for non-numbers or negative input.", "29 => soon, 30 => today, 240 => today, 241 => scheduled.", "NaN and -1 return invalid.", "function deliveryWindow(minutes) { if (typeof minutes !== 'number' || !Number.isFinite(minutes) || minutes < 0) return 'invalid'; if (minutes < 30) return 'soon'; if (minutes <= 240) return 'today'; return 'scheduled'; }", "Check the accepted input domain before applying thresholds.", "The ordered branches make the inclusive 30 and 240 boundaries visible."],
            ["Easy", "Choose a support queue", "Implement supportQueue that maps a non-empty issue type to 'billing', 'account', or 'general'. Match exact lowercase values 'payment' and 'refund' to billing, 'login' and 'password' to account, and all other non-empty strings to general.", "'refund' => billing; 'login' => account; 'crash' => general.", "Whitespace-only input is invalid; do not classify it as general.", "function supportQueue(type) { if (typeof type !== 'string' || !type.trim()) return 'invalid'; if (type === 'payment' || type === 'refund') return 'billing'; if (type === 'login' || type === 'password') return 'account'; return 'general'; }", "Separate input validation from the classification branches.", "Use explicit equality checks so every supported queue rule can be reviewed."],
            ["Medium", "Apply a tiered subscription discount", "Calculate the discount percentage for an annual subscription: 25% for at least 5000 cents, 15% for at least 2000 cents, otherwise 0%. Reject invalid prices, and return both the rate and integer discount cents using rounding down.", "5000 => {rate:0.25,discountCents:1250}; 1999 => {rate:0,discountCents:0}.", "Exactly 2000 qualifies for 15%; negative values are invalid.", "function discountFor(cents) { if (!Number.isSafeInteger(cents) || cents < 0) throw new TypeError('Invalid cents'); const rate = cents >= 5000 ? 0.25 : cents >= 2000 ? 0.15 : 0; return { rate, discountCents: Math.floor(cents * rate) }; }", "Evaluate the highest threshold first so a large amount is not captured by a lower tier.", "Test just below, exactly at, and just above each threshold."],
            ["Medium", "Resolve a feature-access policy", "Implement canExport for a user record. Export is allowed only for an active account and either an admin role or a paid plan; missing fields and unknown status values must deny access.", "{status:'active',role:'member',plan:'pro'} => true; an inactive admin => false.", "Do not treat a truthy string such as 'false' as a boolean permission.", "function canExport(user) { if (!user || user.status !== 'active') return false; return user.role === 'admin' || user.plan === 'pro'; }", "Express the universal prerequisite first, then the two allowed alternatives.", "The final boolean uses strict comparisons and fails closed for incomplete records."],
            ["Hard", "Prioritize an incident by severity and impact", "Implement incidentPriority for severity ('low','medium','high','critical') and affectedUsers. Critical is always P0; high is P0 at 1000 or more users and otherwise P1; medium is P1 at 1000 or more and otherwise P2; low is P2. Invalid severity or negative/non-integer impact returns 'invalid'.", "('high',1000) => P0; ('medium',999) => P2; ('critical',0) => P0.", "A threshold value belongs to the higher-impact branch.", "function incidentPriority(severity, affectedUsers) { const ranks = { low: 'P2', medium: affectedUsers >= 1000 ? 'P1' : 'P2', high: affectedUsers >= 1000 ? 'P0' : 'P1', critical: 'P0' }; if (!Object.hasOwn(ranks, severity) || !Number.isSafeInteger(affectedUsers) || affectedUsers < 0) return 'invalid'; return ranks[severity]; }", "Validate both inputs before reading a severity-specific rule.", "Represent the policy in a decision table and test each row plus the 1000-user boundary."],
            ["Hard", "Prevent an invalid state transition", "Implement nextOrderStatus(current, action) for pending, paid, shipped, and cancelled orders. pending may become paid or cancelled; paid may become shipped or cancelled; shipped and cancelled are terminal. Return the next state or throw an Error for any unsupported transition.", "pending + pay => paid; paid + ship => shipped; shipped + cancel throws.", "Unknown current states and actions are rejected rather than coerced.", "function nextOrderStatus(current, action) { const transitions = { pending: { pay: 'paid', cancel: 'cancelled' }, paid: { ship: 'shipped', cancel: 'cancelled' }, shipped: {}, cancelled: {} }; const next = transitions[current]?.[action]; if (!next) throw new Error('Invalid order transition'); return next; }", "Model permitted transitions as data so terminal states have no outgoing actions.", "A missing lookup means rejection; do not add a catch-all transition."],
        ]
    },
    Loops: {
        hints: ["Identify the accumulator or invariant before choosing the loop form.", "Trace empty input and a boundary item to confirm initialization and termination."],
        items: [
            ["Easy", "Sum only completed lesson minutes", "Implement completedMinutes(sessions) by iterating session records and summing duration only when completed is true. Accept non-negative finite durations; skip invalid records without mutating the list.", "[{completed:true,duration:20},{completed:false,duration:15}] => 20.", "An empty list returns 0, and an invalid duration is ignored.", "function completedMinutes(sessions) { let total = 0; for (const session of sessions) { if (session?.completed === true && Number.isFinite(session.duration) && session.duration >= 0) total += session.duration; } return total; }", "Keep the inclusion condition separate from the running total update.", "Initialize the sum to zero so an empty collection has a valid answer."],
            ["Easy", "Find the first available appointment", "Write firstOpenSlot(slots) that returns the index of the first slot whose available field is exactly true, or -1 when no slot is available. Use an explicit loop and stop as soon as the first match is found.", "[{available:false},{available:true}] => 1.", "An empty list and a list with no true value both return -1.", "function firstOpenSlot(slots) { for (let index = 0; index < slots.length; index += 1) { if (slots[index]?.available === true) return index; } return -1; }", "The requested result is an index, so retain the loop index rather than only the item.", "Return immediately on the first exact true value; otherwise return the sentinel after the loop."],
            ["Medium", "Create a retry schedule", "Implement retryDelays(attempts, baseMs) returning exponential delays baseMs, 2×baseMs, and so on. Require integer attempts from 0 through 10 and finite non-negative baseMs; return an empty array for zero attempts.", "retryDelays(4,100) => [100,200,400,800].", "0 attempts returns []; invalid attempts must throw rather than loop indefinitely.", "function retryDelays(attempts, baseMs) { if (!Number.isInteger(attempts) || attempts < 0 || attempts > 10 || !Number.isFinite(baseMs) || baseMs < 0) throw new RangeError('Invalid retry schedule'); const delays = []; let delay = baseMs; for (let attempt = 0; attempt < attempts; attempt += 1) { delays.push(delay); delay *= 2; } return delays; }", "Use the attempt count as a decreasing loop bound and update delay once per iteration.", "Check zero attempts before assuming the output has any entries."],
            ["Medium", "Validate every row in a CSV import", "Implement validateRows(rows) that returns {valid, errors}. Every row needs a trimmed non-empty email containing one @ and a role of 'student' or 'mentor'. Collect row indexes and field names for all errors, and do not stop at the first invalid row.", "A valid two-row import returns both rows and an empty errors array.", "An empty array is valid; a row with both fields invalid reports both issues.", "function validateRows(rows) { const valid = []; const errors = []; for (const [index, row] of rows.entries()) { const rowErrors = []; const email = typeof row?.email === 'string' ? row.email.trim() : ''; if (!email || email.split('@').length !== 2 || email.startsWith('@') || email.endsWith('@')) rowErrors.push('email'); if (!['student', 'mentor'].includes(row?.role)) rowErrors.push('role'); if (rowErrors.length) errors.push({ index, fields: rowErrors }); else valid.push({ ...row, email }); } return { valid, errors }; }", "Accumulate per-row errors, then choose whether the row belongs in valid output.", "Use entries() to retain the source index and validate each required field independently."],
            ["Hard", "Merge sorted activity streams", "Implement mergeByTime(left,right) for two arrays already sorted by ascending numeric timestamp. Produce a new stable merged array without changing either input; when timestamps tie, preserve the left stream's item first.", "[1,4] merged with [2,4] produces timestamps [1,2,4,4], with the left 4 first.", "Either input may be empty; each source order remains unchanged.", "function mergeByTime(left, right) { const merged = []; let i = 0; let j = 0; while (i < left.length && j < right.length) { if (left[i].time <= right[j].time) merged.push(left[i++]); else merged.push(right[j++]); } while (i < left.length) merged.push(left[i++]); while (j < right.length) merged.push(right[j++]); return merged; }", "Keep one pointer per stream and compare their current unconsumed records.", "Use <= for the tie rule, then append the remainder after one pointer reaches its end."],
            ["Hard", "Detect a stalled pagination loop", "Implement collectPages(fetchPage) that requests pages starting at 1 until a page returns an empty items array. Return all items, but throw if a response repeats the same non-empty cursor twice or reports malformed data. Do not issue more than 100 requests.", "Pages [a,b], [c], [] return [a,b,c].", "A server repeating cursor 'next-2' must stop with an error instead of looping forever.", "async function collectPages(fetchPage) { const items = []; const seen = new Set(); for (let page = 1; page <= 100; page += 1) { const result = await fetchPage(page); if (!result || !Array.isArray(result.items)) throw new TypeError('Malformed page'); if (result.items.length === 0) return items; if (result.nextCursor != null) { if (seen.has(result.nextCursor)) throw new Error('Repeated cursor'); seen.add(result.nextCursor); } items.push(...result.items); } throw new Error('Page limit exceeded'); }", "Define both the normal stopping condition and a hard safety bound before implementing the loop.", "Track opaque cursors in a Set and fail on repetition while allowing a final empty page."],
        ]
    },
    Functions: {
        hints: ["State the function contract in terms of inputs, returned value, and side effects.", "Separate validation from the transformation and test a boundary input before adding branches."],
        items: [
            ["Easy", "Build a reusable slug function", "Implement slugify(title) for article titles: trim surrounding whitespace, lowercase, replace each run of non-letter/non-number characters with one hyphen, and remove leading or trailing hyphens. Do not mutate any external state.", "'  Roadmap: Phase 1! ' => 'roadmap-phase-1'.", "A string containing only punctuation returns an empty slug.", "function slugify(title) { return String(title).trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }", "Keep normalization in a fixed order: trim, lowercase, replace runs, then clean the edges.", "Use a global character-class replacement so punctuation runs become one separator."],
            ["Easy", "Create a defaulted greeting function", "Write greeting(name, options) that returns 'Hello, <name>!' and accepts options with a language of 'en' or 'es'. Use 'friend' for a blank name and English when options or language are omitted; reject unsupported language values.", "greeting('Mira') => 'Hello, Mira!'; greeting(' ',{language:'es'}) => 'Hola, friend!'.", "An unsupported language such as 'fr' throws a RangeError.", "function greeting(name, options = {}) { const clean = typeof name === 'string' && name.trim() ? name.trim() : 'friend'; const language = options.language ?? 'en'; if (language === 'en') return `Hello, ${clean}!`; if (language === 'es') return `Hola, ${clean}!`; throw new RangeError('Unsupported language'); }", "Give the options parameter a default and normalize the display name once.", "Use explicit branches for the supported languages and reject the rest."],
            ["Medium", "Compose price and tax functions", "Implement calculateInvoice using injected priceOf and taxFor functions. It must call priceOf once per item, sum the subtotals, call taxFor once with the subtotal, and return subtotal plus tax without reading globals or changing input records.", "Two item prices 10 and 15 with taxFor(25)=2.5 returns {subtotal:25,tax:2.5,total:27.5}.", "An empty item list calls taxFor(0) and returns a zero subtotal.", "function calculateInvoice(items, priceOf, taxFor) { const subtotal = items.reduce((sum, item) => sum + priceOf(item), 0); const tax = taxFor(subtotal); return { subtotal, tax, total: subtotal + tax }; }", "Inject collaborators as arguments so the function's dependencies are visible and testable.", "Reduce the items to one subtotal, then calculate tax exactly once."],
            ["Medium", "Memoize a one-argument lookup", "Write memoize(fn) for a pure function with string arguments. Return a wrapper that computes each distinct input once, caches even falsy results, and exposes a call count only through a test spy on fn; avoid using truthiness to detect cache hits.", "A memoized lookup called twice with 'x' invokes fn once.", "If fn returns 0 or undefined, the second same-key call is still a cache hit.", "function memoize(fn) { const cache = new Map(); return (key) => { if (cache.has(key)) return cache.get(key); const value = fn(key); cache.set(key, value); return value; }; }", "A Map has a separate has operation, so cached falsy values are unambiguous.", "Store the result immediately after the first calculation and return the stored value on later calls."],
            ["Hard", "Add cancellation and cleanup to a task runner", "Implement runTask(task, signal) that invokes an async task with the signal, returns its result, and always calls task.cleanup exactly once when provided, whether task succeeds, rejects, or is already aborted. Preserve the original task error if cleanup also fails.", "A successful task returns its value and runs cleanup once.", "If both task and cleanup reject, the caller receives the task rejection.", "async function runTask(task, signal) { let taskError; try { if (signal?.aborted) throw new DOMException('Aborted', 'AbortError'); return await task.run(signal); } catch (error) { taskError = error; throw error; } finally { if (typeof task.cleanup === 'function') { try { await task.cleanup(); } catch (cleanupError) { if (!taskError) throw cleanupError; } } } }", "Use try/finally for cleanup and remember whether the main operation already failed.", "Throw cleanup failure only when there is no earlier task error to preserve."],
            ["Hard", "Implement a bounded retry wrapper", "Create retry(operation, options) with attempts, shouldRetry, and delay functions. Call operation with a one-based attempt number; retry only when shouldRetry(error, attempt) is true and attempts remain; await delay between attempts and finally rethrow the last operation error.", "With attempts=3 and two transient errors, operation is called three times and returns the third result.", "With attempts=1, delay is never called; a non-retryable first error is rethrown immediately.", "async function retry(operation, { attempts, shouldRetry, delay }) { if (!Number.isInteger(attempts) || attempts < 1) throw new RangeError('attempts must be positive'); for (let attempt = 1; attempt <= attempts; attempt += 1) { try { return await operation(attempt); } catch (error) { if (attempt === attempts || !shouldRetry(error, attempt)) throw error; await delay(attempt); } } }", "Make the retry decision in the catch path using both remaining attempts and the policy callback.", "Await the delay only before a retry, and let the final error escape unchanged."],
        ]
    },
    Arrays: {
        hints: ["Choose the array operation from the desired relationship between input items and output items.", "Preserve source data by returning new arrays or objects; check empty arrays and ties explicitly."],
        items: [
            ["Easy", "Extract unique skill labels", "Implement uniqueSkills(records) returning trimmed, case-insensitive unique skill names in first-seen order. Ignore missing, non-string, and blank values; preserve the casing of the first accepted spelling.", "['React',' react ','SQL'] => ['React','SQL'].", "An empty list returns [] and repeated labels differing only in case appear once.", "function uniqueSkills(records) { const seen = new Set(); const result = []; for (const record of records) { if (typeof record?.skill !== 'string') continue; const skill = record.skill.trim(); const key = skill.toLowerCase(); if (skill && !seen.has(key)) { seen.add(key); result.push(skill); } } return result; }", "Use one normalized key for comparison while keeping the original trimmed label for display.", "Append only when the key has not been seen, which preserves first-seen order."],
            ["Easy", "Transform scores into grade labels", "Write gradeCards(scores) that maps each numeric score to an object with the original score and label: pass for 60 or higher, review below 60. Reject non-finite values by mapping them to label 'invalid'; do not mutate the scores array.", "[90,59] => [{score:90,label:'pass'},{score:59,label:'review'}].", "NaN maps to invalid and an empty array remains empty.", "function gradeCards(scores) { return scores.map((score) => ({ score, label: Number.isFinite(score) ? (score >= 60 ? 'pass' : 'review') : 'invalid' })); }", "map should produce exactly one card for every input position.", "Use a finite-number guard before comparing the threshold."],
            ["Medium", "Group applications by status", "Implement groupApplications(applications) returning arrays keyed by each record's status. Skip records without a non-empty string status, preserve input order within each group, and leave the source array untouched.", "Statuses ['new','review','new'] produce new with first and third records, review with the second.", "An empty input returns an empty object, not an object with invented groups.", "function groupApplications(applications) { return applications.reduce((groups, application) => { const status = application?.status; if (typeof status !== 'string' || !status.trim()) return groups; (groups[status] ||= []).push(application); return groups; }, {}); }", "Initialize each group on its first valid occurrence and append as you traverse.", "A single reduce pass preserves the order of records in each status group."],
            ["Medium", "Paginate a client-side result list", "Write pageItems(items, page, pageSize) using one-based pages. Require positive integer page and pageSize, return the selected slice, and return [] when page is beyond the available items.", "pageItems([a,b,c,d],2,2) => [c,d].", "For an empty list page 1 returns []; page 0 throws a RangeError.", "function pageItems(items, page, pageSize) { if (!Number.isInteger(page) || page < 1 || !Number.isInteger(pageSize) || pageSize < 1) throw new RangeError('Invalid pagination'); const start = (page - 1) * pageSize; return items.slice(start, start + pageSize); }", "Convert a one-based page into a zero-based start offset.", "slice naturally returns an empty array when the requested offset exceeds the list."],
            ["Hard", "Build a stable leaderboard", "Implement leaderboard(entries) sorted by score descending, then completion time ascending, then original input order. Return new copies with one-based rank; do not mutate input records or use rank as a tie-breaker.", "Equal score entries with earlier time rank first; exact ties retain source order.", "The input array and its objects remain unchanged.", "function leaderboard(entries) { return entries.map((entry, index) => ({ entry, index })).sort((a, b) => b.entry.score - a.entry.score || a.entry.completedAt - b.entry.completedAt || a.index - b.index).map(({ entry }, index) => ({ ...entry, rank: index + 1 })); }", "Decorate records with their original index so the final tie-break is explicit.", "Sort the decorated copy, then create fresh result objects with their ranks."],
            ["Hard", "Compute a rolling availability window", "Given daily capacity values, implement rollingMinimum(values, windowSize) returning the minimum for every full contiguous window. Require positive integer window size; return [] when it exceeds the input length and do not mutate input.", "[5,2,4,1] with size 2 => [2,2,1].", "A window of size 1 returns a copy of the original values.", "function rollingMinimum(values, windowSize) { if (!Number.isInteger(windowSize) || windowSize < 1) throw new RangeError('Invalid window size'); const result = []; for (let start = 0; start + windowSize <= values.length; start += 1) { let minimum = Infinity; for (let index = start; index < start + windowSize; index += 1) minimum = Math.min(minimum, values[index]); result.push(minimum); } return result; }", "Define the last valid start index as values.length - windowSize.", "For each full window scan its values and append one minimum; this direct approach is O(n × windowSize)."],
        ]
    },
    Objects: {
        hints: ["Decide whether the operation should preserve, transform, or safely query the object.", "Check ownership, missing keys, and nested references; object spread copies only one level."],
        items: [
            ["Easy", "Read optional contact details safely", "Implement contactLabel(profile) using an optional nested contact object. Return the trimmed email when present, otherwise the trimmed phone, otherwise 'No contact provided'. Ignore non-string values and do not throw for missing nested objects.", "{contact:{email:' a@b.test '}} => 'a@b.test'; an empty profile => 'No contact provided'.", "A numeric email field is ignored and the phone fallback is still considered.", "function contactLabel(profile) { const email = profile?.contact?.email; if (typeof email === 'string' && email.trim()) return email.trim(); const phone = profile?.contact?.phone; if (typeof phone === 'string' && phone.trim()) return phone.trim(); return 'No contact provided'; }", "Optional chaining protects only the path lookup; still validate the final value's type.", "Check the preferred field first, then use the documented fallback order."],
            ["Easy", "Count own preference keys", "Write preferenceCount(settings) that counts only enumerable own keys whose values are not undefined. Do not count inherited properties and handle a null or non-object input as zero.", "An object with two own defined settings returns 2, even if its prototype has another key.", "undefined-valued own keys are excluded; false and 0 count as configured values.", "function preferenceCount(settings) { if (settings === null || typeof settings !== 'object') return 0; return Object.keys(settings).filter((key) => settings[key] !== undefined).length; }", "Object.keys lists own enumerable string keys, unlike a for...in loop.", "Test value presence with !== undefined so false and zero are retained."],
            ["Medium", "Apply a shallow settings patch", "Implement patchSettings(current, patch) that returns a new settings object, replaces only supplied top-level keys, ignores keys named __proto__, constructor, or prototype, and does not mutate either input.", "{theme:'dark',density:'cozy'} patched with {theme:'light'} preserves density.", "A patch containing __proto__ must not change the result's prototype.", "function patchSettings(current, patch) { const safePatch = {}; for (const [key, value] of Object.entries(patch || {})) { if (!['__proto__', 'constructor', 'prototype'].includes(key)) safePatch[key] = value; } return { ...(current || {}), ...safePatch }; }", "Build a fresh object and filter unsafe keys before spreading patch values.", "A shallow merge intentionally replaces a nested value as a whole; document that contract."],
            ["Medium", "Index projects by their stable ID", "Create indexProjects(projects) returning an object keyed by non-empty string IDs. Skip invalid IDs and keep the first project when duplicate IDs appear so an accidental later duplicate cannot silently replace earlier data.", "[{id:'p1',name:'A'},{id:'p1',name:'B'}] keeps project A under p1.", "An empty input returns {}; a numeric ID is skipped.", "function indexProjects(projects) { const byId = Object.create(null); for (const project of projects) { if (typeof project?.id !== 'string' || !project.id.trim()) continue; if (!Object.hasOwn(byId, project.id)) byId[project.id] = project; } return byId; }", "Validate and trim the identifier before using it as a dictionary key.", "Use a null-prototype dictionary and Object.hasOwn to avoid special object keys and inherited names."],
            ["Hard", "Compare nested profile changes", "Implement changedProfileFields(before, after) for the known fields name, email, and location.city. Return the top-level labels for fields whose values differ, treating missing and undefined as equivalent but keeping null distinct.", "A changed city returns ['location.city']; unchanged absent fields return [].", "null versus missing is a change; missing versus undefined is not.", "function changedProfileFields(before, after) { const paths = ['name', 'email', 'location.city']; return paths.filter((path) => { const read = (object) => path.split('.').reduce((value, key) => value == null ? undefined : value[key], object); return !Object.is(read(before), read(after)); }); }", "Declare the paths the product considers meaningful rather than deep-comparing arbitrary payloads.", "A path reader can map absent traversal to undefined while Object.is preserves null distinction."],
            ["Hard", "Create a safe public profile projection", "Write publicProfile(user) that returns only displayName and avatarUrl from a user object, trims non-empty strings, and omits absent or invalid fields. Never spread the original user object, which may contain email, roles, or private settings.", "A user with displayName, avatarUrl, and private email returns only the first two fields.", "Null input and blank strings return an empty projection.", "function publicProfile(user) { const result = {}; for (const key of ['displayName', 'avatarUrl']) { const value = user?.[key]; if (typeof value === 'string' && value.trim()) result[key] = value.trim(); } return result; }", "Build an allowlisted projection instead of removing known private fields from a full object.", "Copy only validated public fields so future model additions cannot leak by default."],
        ]
    },
    DOM: {
        hints: ["Prefer safe text APIs and explicit null checks when working with browser nodes.", "Separate event setup from rendering updates and account for cleanup or repeated calls."],
        items: [
            ["Easy", "Update a status node safely", "Implement renderStatus(root, message) to find [data-status] and set its text. Return false if the node is absent and true when updated; treat message as plain text, never markup.", "A message '<b>Ready</b>' is displayed literally as text.", "A missing node returns false without throwing.", "function renderStatus(root, message) { const node = root?.querySelector('[data-status]'); if (!node) return false; node.textContent = String(message); return true; }", "Query inside the supplied root so the function does not depend on a global document.", "Use textContent for untrusted plain text and return an explicit success result."],
            ["Easy", "Build a DOM list from labels", "Write createSkillList(document, skills) that returns a ul with one li per non-empty string skill. Trim labels, create nodes with DOM methods, and never interpolate input into innerHTML.", "[' React ','SQL'] creates two list items containing React and SQL.", "Blank and non-string values are skipped; zero accepted skills returns an empty ul.", "function createSkillList(document, skills) { const list = document.createElement('ul'); for (const value of skills) { if (typeof value !== 'string' || !value.trim()) continue; const item = document.createElement('li'); item.textContent = value.trim(); list.append(item); } return list; }", "Create elements and assign text rather than concatenating markup strings.", "An empty list is still a valid result and keeps the caller's rendering contract simple."],
            ["Medium", "Delegate clicks in a dynamic menu", "Implement attachMenuHandler(menu, onSelect) using one click listener on the menu. Invoke onSelect with the nearest button's data-action only when that button is inside the menu; return a cleanup function that removes the listener.", "Clicking a nested span inside a menu button selects its action.", "A button outside the menu or an element without data-action is ignored.", "function attachMenuHandler(menu, onSelect) { const handle = (event) => { const button = event.target.closest('button[data-action]'); if (button && menu.contains(button)) onSelect(button.dataset.action); }; menu.addEventListener('click', handle); return () => menu.removeEventListener('click', handle); }", "Event delegation listens on a stable parent and resolves the intended child from the event target.", "Return a cleanup closure that removes the exact same handler reference."],
            ["Medium", "Synchronize a character counter", "Create updateCounter(input, output, maximum) that writes '<length> / <maximum>' using textContent, toggles an over-limit class when needed, and responds correctly when the input is empty. Return a cleanup function for the input event listener.", "Input 'hello' with max 10 displays '5 / 10' and removes over-limit.", "At maximum + 1 the class is set; cleanup prevents later updates.", "function updateCounter(input, output, maximum) { const update = () => { const length = input.value.length; output.textContent = `${length} / ${maximum}`; output.classList.toggle('over-limit', length > maximum); }; input.addEventListener('input', update); update(); return () => input.removeEventListener('input', update); }", "Use the input event so typing, paste, and deletion all refresh the counter.", "Run one initial update and keep a stable function reference for removal."],
            ["Hard", "Implement an accessible disclosure", "Build setupDisclosure(button, panel) so it toggles hidden state and aria-expanded on click, synchronizes the initial state, and supports Enter/Space through the native button behavior. Return cleanup. Do not add redundant keyboard listeners to a button.", "Initially collapsed means panel.hidden is true and aria-expanded is 'false'.", "Two clicks restore the initial state and cleanup removes the listener.", "function setupDisclosure(button, panel) { const sync = (expanded) => { panel.hidden = !expanded; button.setAttribute('aria-expanded', String(expanded)); }; sync(button.getAttribute('aria-expanded') === 'true'); const onClick = () => sync(button.getAttribute('aria-expanded') !== 'true'); button.addEventListener('click', onClick); return () => button.removeEventListener('click', onClick); }", "Use the native button click activation, which already covers keyboard activation.", "Keep aria-expanded as the source of the current state and update both DOM properties together."],
            ["Hard", "Render a safe search result fragment", "Implement renderSearchResults(container, records, query) that replaces the container children with matching records whose title contains the case-insensitive query. Create an article and heading per match using textContent; never use innerHTML. Return the match count.", "Query 'api' matches 'API Design' and renders the exact title as text.", "A title containing '<script>' is rendered literally and cannot create an element.", "function renderSearchResults(container, records, query) { const needle = query.trim().toLowerCase(); const matches = records.filter((record) => String(record.title ?? '').toLowerCase().includes(needle)); const fragment = container.ownerDocument.createDocumentFragment(); for (const record of matches) { const article = container.ownerDocument.createElement('article'); const heading = container.ownerDocument.createElement('h2'); heading.textContent = String(record.title ?? ''); article.append(heading); fragment.append(article); } container.replaceChildren(fragment); return matches.length; }", "Filter data before creating nodes and use the container's ownerDocument for testability.", "Build a fragment with text nodes, then replace the old result set in one operation."],
        ]
    },
    Events: {
        hints: ["Choose the event that represents the user's intent, then prevent defaults only when replacing browser behavior.", "Read current input from the event target and keep listener registration paired with cleanup."],
        items: [
            ["Easy", "Handle a search form submission", "Attach a submit handler to a search form that prevents page navigation, trims the named query field, and calls onSearch with the resulting string. Return a cleanup function.", "Submitting a field with '  roadmap ' calls onSearch('roadmap').", "A blank submission calls onSearch('') once and does not reload the page.", "function attachSearch(form, onSearch) { const handle = (event) => { event.preventDefault(); const data = new FormData(form); onSearch(String(data.get('query') ?? '').trim()); }; form.addEventListener('submit', handle); return () => form.removeEventListener('submit', handle); }", "Listen for submit on the form so Enter and the submit button share one path.", "Prevent the default navigation, normalize the field value, then invoke the supplied callback."],
            ["Easy", "Ignore a disabled action button", "Implement bindAction(button, action) so clicks call action exactly once only when the button is enabled. Do not register repeated listeners if bindAction is called again for the same button; return cleanup.", "An enabled button click calls action once.", "A disabled button causes no call, and cleanup means later clicks do nothing.", String.raw`const actionBindings = new WeakMap();
function bindAction(button, action) { actionBindings.get(button)?.(); const handler = () => { if (!button.disabled) action(); }; button.addEventListener('click', handler); const cleanup = () => button.removeEventListener('click', handler); actionBindings.set(button, cleanup); return () => { cleanup(); if (actionBindings.get(button) === cleanup) actionBindings.delete(button); }; }`, "Keep the cleanup function associated with the element in a WeakMap so rebinding can remove the old listener.", "Check disabled at click time because the state may change after registration."],
            ["Medium", "Debounce a live preview", "Implement listenWithDebounce(input, callback, wait) that calls callback with the latest value after no input for wait milliseconds. Clear a pending timer on new input and on cleanup; cleanup must prevent future calls.", "Typing 'a' then 'ab' within the wait interval reports only 'ab'.", "Calling cleanup before the timer expires results in no callback.", "function listenWithDebounce(input, callback, wait) { let timer; const handle = () => { clearTimeout(timer); const value = input.value; timer = setTimeout(() => callback(value), wait); }; input.addEventListener('input', handle); return () => { clearTimeout(timer); input.removeEventListener('input', handle); }; }", "Each new input cancels the previously scheduled callback.", "Capture the current value when scheduling and clear both timer and listener during cleanup."],
            ["Medium", "Avoid duplicate outside-click handlers", "Create attachOutsideDismiss(panel, onDismiss) that listens on the document and calls onDismiss only when a pointer event target is outside the panel. Return cleanup and ensure events inside descendants do not dismiss.", "A click on a nested button inside the panel does not dismiss.", "A click on a sibling outside calls onDismiss once.", "function attachOutsideDismiss(panel, onDismiss) { const handle = (event) => { if (!panel.contains(event.target)) onDismiss(); }; panel.ownerDocument.addEventListener('pointerdown', handle); return () => panel.ownerDocument.removeEventListener('pointerdown', handle); }", "Test containment against the event target, which may be a nested child.", "Register on the owning document so the helper also works with an embedded document in tests."],
            ["Hard", "Coordinate keyboard shortcuts with focused inputs", "Implement attachSaveShortcut(target, save) for Ctrl/Cmd+S. Call save and prevent the browser default only when the shortcut is pressed outside input, textarea, select, or contenteditable elements. Return cleanup.", "Meta+S on a normal page region saves; Ctrl+S while typing in a textarea is untouched.", "Unrelated keys and Alt+S do nothing.", "function attachSaveShortcut(target, save) { const handler = (event) => { const key = event.key.toLowerCase(); if (!(event.ctrlKey || event.metaKey) || event.altKey || key !== 's') return; const element = event.target; const editing = element?.isContentEditable || ['INPUT', 'TEXTAREA', 'SELECT'].includes(element?.tagName); if (editing) return; event.preventDefault(); save(); }; target.addEventListener('keydown', handler); return () => target.removeEventListener('keydown', handler); }", "Filter by modifier and key before inspecting the target's editing behavior.", "Leave native browser behavior unchanged for fields where the user may be editing text."],
            ["Hard", "Sequence asynchronous event handlers", "Implement createSerialHandler(handle) returning an event listener that processes events in order, awaiting each handle call. If one call rejects, report it through onError and continue processing later queued events; provide a flush method for tests.", "Three rapid events are handled in their original order.", "The second failure is reported but does not prevent the third event from running.", "function createSerialHandler(handle, onError = () => {}) { let queue = Promise.resolve(); const listener = (event) => { queue = queue.then(() => handle(event)).catch((error) => { onError(error); }); }; listener.flush = () => queue; return listener; }", "Chain each event onto one promise queue rather than starting parallel handlers.", "Catch per queued operation so the queue recovers after a failed handler."],
        ]
    },
    "ES6+": {
        hints: ["Use modern syntax where it clarifies the data contract, while remembering shallow copying and iteration semantics.", "Check that the returned value preserves the required ordering and does not mutate the source."],
        items: [
            ["Easy", "Destructure an API card with defaults", "Implement cardFromJob(job) using destructuring defaults for missing company and location. Return only title, company, and location, preserving an explicitly empty string instead of replacing it with a default.", "{title:'Engineer'} => {title:'Engineer',company:'Unknown company',location:'Location not provided'}.", "A provided company:'' remains empty because destructuring defaults apply only to undefined.", "function cardFromJob(job) { const { title, company = 'Unknown company', location = 'Location not provided' } = job; return { title, company, location }; }", "Destructuring defaults cover absent or undefined properties but not null or empty strings.", "Return an allowlisted object with exactly the display fields needed."],
            ["Easy", "Use rest parameters for a score average", "Write averageScore(first, ...remaining) that averages all finite numeric arguments and throws if there are no arguments or any non-number/invalid score. Do not rely on arguments in an arrow function.", "averageScore(8,10,6) => 8.", "averageScore() and averageScore(5,NaN) throw a TypeError.", "function averageScore(first, ...remaining) { const values = [first, ...remaining]; if (!values.length || values.some((value) => typeof value !== 'number' || !Number.isFinite(value))) throw new TypeError('Scores must be finite numbers'); return values.reduce((sum, value) => sum + value, 0) / values.length; }", "Rest collects the remaining call arguments into a real array.", "Validate the complete array before summing so invalid values cannot produce a misleading average."],
            ["Medium", "Update nested settings immutably", "Use object spread to create an updated user settings object with a new notifications.email value, preserving other notification settings and unrelated profile fields. Neither the original object nor its nested notifications object may be mutated.", "Turning email off preserves notifications.sms and profile.name.", "The original object still has its original email setting after the update.", "function setEmailNotifications(user, enabled) { return { ...user, settings: { ...user.settings, notifications: { ...user.settings.notifications, email: enabled } } }; }", "Spread each object along the changed path; a top-level copy alone is shallow.", "Create copies at user, settings, and notifications levels before setting the changed leaf."],
            ["Medium", "Normalize tagged records with a Map", "Implement indexByCategory(records) using a Map keyed by category. Ignore records with a missing category, preserve each category's input order, and return the Map rather than converting keys into a plain object.", "Two records in category 'constructor' remain safely grouped together.", "An empty collection returns an empty Map and does not collide with object prototype names.", "function indexByCategory(records) { const groups = new Map(); for (const record of records) { if (typeof record?.category !== 'string' || !record.category) continue; if (!groups.has(record.category)) groups.set(record.category, []); groups.get(record.category).push(record); } return groups; }", "Map supports arbitrary string keys without prototype-property behavior.", "Initialize a category once, then append every matching record in source order."],
            ["Hard", "Write a lazy generator for calendar days", "Implement a generator daysBetween(start, end) yielding UTC ISO date strings from start through end inclusively. Require valid dates with start not after end, and increment using UTC date arithmetic so daylight-saving changes cannot skip a day.", "2024-02-28 through 2024-03-01 yields Feb 28, Feb 29, Mar 1.", "Equal dates yield exactly one date; reversed dates throw a RangeError.", "function* daysBetween(start, end) { const current = new Date(`${start}T00:00:00.000Z`); const last = new Date(`${end}T00:00:00.000Z`); if (!Number.isFinite(current.getTime()) || !Number.isFinite(last.getTime()) || current > last) throw new RangeError('Invalid date range'); while (current <= last) { yield current.toISOString().slice(0, 10); current.setUTCDate(current.getUTCDate() + 1); } }", "A generator yields one date at a time and keeps the current date as its local iteration state.", "Use UTC midnight and setUTCDate so iteration does not depend on local daylight-saving transitions."],
            ["Hard", "Compose a pipeline with reusable transforms", "Build a pipeline(...transforms) function returning a function that applies transforms left to right to one value. Reject any non-function stage at construction and do not mutate the transforms array.", "pipeline(trim, lowercase)(' Hello ') => 'hello'.", "No stages returns the input unchanged; an invalid stage throws before any pipeline execution.", "function pipeline(...transforms) { if (transforms.some((transform) => typeof transform !== 'function')) throw new TypeError('Every stage must be a function'); return (input) => transforms.reduce((value, transform) => transform(value), input); }", "Validate stages once when defining the pipeline, not on every data item.", "reduce carries the prior stage's output into the next stage and naturally handles zero stages."],
        ]
    },
    Promises: {
        hints: ["A Promise chain passes each returned value to the next then callback and sends thrown errors to a rejection handler.", "Test both settlement paths and ensure each asynchronous step returns or awaits its next operation."],
        items: [
            ["Easy", "Transform a fulfilled request result", "Implement parseCount(promise) that returns a Promise resolving to the numeric count from a fulfilled object. Reject when count is not a finite non-negative number; preserve an existing rejection.", "Promise.resolve({count:4}) resolves to 4.", "A string count '4' is rejected rather than silently coerced.", "function parseCount(promise) { return promise.then((result) => { if (typeof result?.count !== 'number' || !Number.isFinite(result.count) || result.count < 0) throw new TypeError('Invalid count'); return result.count; }); }", "Return the transformed value from then; a thrown validation error becomes a rejection.", "Do not catch and replace the original rejected promise unless the contract asks for recovery."],
            ["Easy", "Run cleanup after a Promise settles", "Write withCleanup(operation, cleanup) that returns the operation's value or rejection and calls cleanup exactly once after either outcome. If cleanup rejects after a successful operation, propagate the cleanup error; if the operation rejects, preserve that original error.", "A resolved operation returns its value and records one cleanup call.", "When both operation and cleanup reject, the caller receives the operation error.", "function withCleanup(operation, cleanup) { return Promise.resolve().then(operation).then(async (value) => { await cleanup(); return value; }, async (error) => { try { await cleanup(); } catch {} throw error; }); }", "Use separate fulfillment and rejection branches so cleanup failure cannot mask an operation failure.", "Await cleanup in both branches and return or rethrow the original outcome."],
            ["Medium", "Run independent profile requests together", "Implement loadProfile(userId, getProfile, getSkills) that starts both independent Promise-returning calls without serial waiting and resolves to {profile, skills}. If either rejects, the returned promise rejects.", "Both results are combined after both operations finish.", "A rejection from either request is not converted into a successful partial profile.", "function loadProfile(userId, getProfile, getSkills) { return Promise.all([getProfile(userId), getSkills(userId)]).then(([profile, skills]) => ({ profile, skills })); }", "Independent requests can be started together in Promise.all.", "Destructure the resolved pair in the same order as the input promises."],
            ["Medium", "Recover from a cache miss but not a server error", "Write getWithCache(cacheRead, networkRead) that calls networkRead only when cacheRead rejects with an error whose code is CACHE_MISS. All other cache errors and network errors must remain rejected.", "A CACHE_MISS reads the network once and returns its result.", "A permission error from cacheRead is propagated without a network call.", "function getWithCache(cacheRead, networkRead) { return cacheRead().catch((error) => { if (error?.code !== 'CACHE_MISS') throw error; return networkRead(); }); }", "Recovery belongs in catch but should branch on a documented error code.", "Rethrow unknown cache failures so operational problems are not hidden."],
            ["Hard", "Implement a concurrency-limited promise pool", "Create mapLimit(items, limit, mapper) that preserves result order while running at most limit mapper calls concurrently. Reject invalid limits and reject the returned Promise if any mapper rejects.", "Five items with limit 2 complete in source order while peak active count never exceeds 2.", "An empty list resolves to []; limit 0 throws a RangeError.", "async function mapLimit(items, limit, mapper) { if (!Number.isInteger(limit) || limit < 1) throw new RangeError('Invalid limit'); const results = new Array(items.length); let next = 0; async function worker() { while (true) { const index = next++; if (index >= items.length) return; results[index] = await mapper(items[index], index); } } await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker)); return results; }", "Share a monotonically increasing next index among a fixed number of workers.", "Store each mapped result at its original index so completion timing does not change output order."],
            ["Hard", "Add timeout without leaking a timer", "Implement withTimeout(promise, milliseconds) that rejects with a TimeoutError if the input remains pending past the duration, clears its timer after either settlement, and otherwise preserves the input value or rejection.", "A fast fulfilled promise returns its value and clears the timeout.", "A never-settling promise rejects after the duration; a rejection before timeout stays unchanged.", "function withTimeout(promise, milliseconds) { return new Promise((resolve, reject) => { const timer = setTimeout(() => reject(new Error('TimeoutError')), milliseconds); Promise.resolve(promise).then((value) => { clearTimeout(timer); resolve(value); }, (error) => { clearTimeout(timer); reject(error); }); }); }", "Race the operation against a timer, but ensure the losing timer is cleared.", "Attach both fulfillment and rejection handlers so original outcomes pass through unchanged."],
        ]
    },
    "Async/Await": {
        hints: ["Await only where the next step depends on the previous result; use try/catch for expected rejection paths.", "Remember that HTTP error responses resolve fetch; inspect response.ok before parsing success data."],
        items: [
            ["Easy", "Load JSON with async/await", "Implement readJson(response) using async/await. Reject with an Error containing the HTTP status when response.ok is false; otherwise return parsed JSON and allow JSON parsing errors to propagate.", "A successful response with {ok:true,json:async()=>({items:[]})} returns {items:[]}.", "A 404 response rejects before json() is called.", "async function readJson(response) { if (!response.ok) throw new Error(`HTTP ${response.status}`); return await response.json(); }", "Check the Response status explicitly before parsing its body.", "Let json() errors retain their native rejection rather than disguising malformed JSON as success."],
            ["Easy", "Return a safe loading result", "Write loadDashboard(fetchData) that awaits data and returns {status:'success', data}. If fetchData rejects, return {status:'error', message:'Unable to load dashboard'} without exposing internal error messages.", "A rejection containing a database URI results only in the generic message.", "Successful falsy data such as 0 is still returned as data:0.", "async function loadDashboard(fetchData) { try { return { status: 'success', data: await fetchData() }; } catch { return { status: 'error', message: 'Unable to load dashboard' }; } }", "Place the awaited call inside try so both synchronous throws and promise rejections are caught.", "Return the supplied value without testing truthiness; keep errors generic for the caller."],
            ["Medium", "Fetch independent panels concurrently", "Implement loadWorkspace(getJobs, getTasks) to await two independent calls concurrently and return both datasets. If either fails, reject with a stable WorkspaceLoadError while keeping the original error as cause.", "Successful calls return {jobs, tasks}.", "If one call rejects, the wrapper error has name WorkspaceLoadError and its cause is the original failure.", "async function loadWorkspace(getJobs, getTasks) { try { const [jobs, tasks] = await Promise.all([getJobs(), getTasks()]); return { jobs, tasks }; } catch (cause) { const error = new Error('Workspace data unavailable', { cause }); error.name = 'WorkspaceLoadError'; throw error; } }", "Promise.all expresses that both results are required and starts both calls immediately.", "Use the Error cause option to preserve diagnostics without exposing raw details in the UI."],
            ["Medium", "Process a queue sequentially", "Write processQueue(items, process) that awaits each item in input order, collects results, and stops on the first rejection. Do not start later work after a failure.", "Items [a,b,c] are processed a then b then c.", "If b rejects, c is never processed and the returned promise rejects with b's error.", "async function processQueue(items, process) { const results = []; for (const [index, item] of items.entries()) results.push(await process(item, index)); return results; }", "A for...of loop with await makes the sequencing explicit.", "Push only after the current operation succeeds; rejection naturally stops iteration."],
            ["Hard", "Cancel a stale search request", "Implement searchLatest(query, fetchResults, controllerRef) that aborts the previous request, creates and stores a new AbortController, then returns the new fetchResults promise with its signal. Do not convert AbortError into an empty successful result.", "Starting query 'react' after 'rea' aborts the first controller.", "An AbortError remains a rejected promise so the caller can distinguish stale work.", "async function searchLatest(query, fetchResults, controllerRef) { controllerRef.current?.abort(); const controller = new AbortController(); controllerRef.current = controller; return fetchResults(query, { signal: controller.signal }); }", "Keep the current controller in a shared reference so a later request can abort it.", "Do not swallow abort rejection; the caller can ignore stale results using the request identity."],
            ["Hard", "Ensure parallel tasks settle before reporting", "Implement settleAll(tasks) that awaits every task and returns records of {status:'fulfilled',value} or {status:'rejected',reason}. One task failure must not cause early return while others continue running.", "A fulfilled task and rejected task produce one record of each status.", "An empty task list returns []; rejection reasons remain attached to their records.", "async function settleAll(tasks) { return await Promise.all(tasks.map((task) => Promise.resolve(task).then((value) => ({ status: 'fulfilled', value }), (reason) => ({ status: 'rejected', reason })))); }", "Convert each task outcome into a fulfilled Promise before using Promise.all.", "Both branches should return a tagged record so all work is awaited."],
        ]
    },
    "Fetch API": {
        hints: ["Treat request construction, HTTP status, and response parsing as separate validation steps.", "Use URL and URLSearchParams for query encoding, and never display a successful state before checking response.ok."],
        items: [
            ["Easy", "Encode a job search query", "Implement buildSearchUrl(base, query) that appends a q query parameter using URL and URLSearchParams while preserving any existing base query parameters.", "'/api/jobs?limit=10' plus 'C++ engineer' includes an encoded q value and keeps limit=10.", "An empty query still produces a valid URL with q='', without concatenating a second question mark.", "function buildSearchUrl(base, query) { const url = new URL(base, 'https://example.test'); url.searchParams.set('q', query); return `${url.pathname}${url.search}`; }", "Let URLSearchParams handle reserved characters such as spaces and plus signs.", "Set the parameter instead of manually adding a query string delimiter."],
            ["Easy", "Separate HTTP failure from network failure", "Write fetchText(fetcher, url) that returns response text for successful HTTP responses and throws an error with the status for non-2xx responses. Network rejections should propagate unchanged.", "A 200 response resolves to its text.", "A 500 response throws with status 500 and does not call response.text().", "async function fetchText(fetcher, url) { const response = await fetcher(url); if (!response.ok) { const error = new Error(`HTTP ${response.status}`); error.status = response.status; throw error; } return response.text(); }", "Fetch rejects for network failures, but an HTTP 500 still resolves to a Response.", "Check ok before reading the response body and preserve the status on the thrown error."],
            ["Medium", "Add JSON headers only when there is a body", "Implement requestOptions(method, body) that returns a fetch options object. For a provided body, JSON.stringify it and add application/json; for undefined body, omit both body and Content-Type. Preserve the supplied method.", "POST with an object has method, JSON body, and JSON content type.", "GET with undefined body does not contain body or Content-Type keys.", "function requestOptions(method, body) { const options = { method }; if (body !== undefined) { options.headers = { 'Content-Type': 'application/json' }; options.body = JSON.stringify(body); } return options; }", "Distinguish an omitted body from valid falsy JSON values such as null, false, and zero.", "Use body !== undefined rather than a truthiness test before serialization."],
            ["Medium", "Handle paginated fetch results safely", "Write fetchAllPages(fetchPage) that appends each page's data array until pagination.hasNext is false. Reject malformed envelopes and reject repeated page tokens; pass the current token to fetchPage.", "Two pages followed by hasNext false return the concatenated data in order.", "A repeated nextToken or missing data array rejects rather than looping or returning partial success.", "async function fetchAllPages(fetchPage) { const all = []; const seen = new Set(); let token; do { const page = await fetchPage(token); if (!page || !Array.isArray(page.data) || typeof page.pagination?.hasNext !== 'boolean') throw new TypeError('Malformed page'); all.push(...page.data); const next = page.pagination.nextToken; if (!page.pagination.hasNext) return all; if (typeof next !== 'string' || seen.has(next)) throw new Error('Invalid or repeated page token'); seen.add(next); token = next; } while (true); }", "Validate the response envelope before appending or following its cursor.", "A cursor must advance; a repeated token is a protocol failure and must terminate the loop."],
            ["Hard", "Retry only idempotent GET requests", "Implement fetchWithRetry(fetcher, url, attempts, delay) for GET requests only. Retry network errors and HTTP 503, stop immediately on other HTTP errors, and return a successful Response. Do not retry after attempts are exhausted.", "A network failure then 200 returns the successful Response.", "A 401 is not retried, and a final 503 is thrown after the configured attempts.", "async function fetchWithRetry(fetcher, url, attempts, delay) { let lastError; for (let attempt = 1; attempt <= attempts; attempt += 1) { try { const response = await fetcher(url, { method: 'GET' }); if (response.ok) return response; if (response.status !== 503) throw Object.assign(new Error(`HTTP ${response.status}`), { status: response.status }); lastError = Object.assign(new Error('Service unavailable'), { status: 503 }); } catch (error) { if (error.status && error.status !== 503) throw error; lastError = error; } if (attempt < attempts) await delay(attempt); } throw lastError; }", "Classify HTTP status separately from fetch network errors before deciding to retry.", "Keep retries bounded and wait only when another attempt will actually occur."],
            ["Hard", "Prevent stale search responses", "Design latestResults(query, request, state) so each request receives an increasing sequence ID. Return results only when the response belongs to the latest issued request; older responses must be marked stale and must not replace current state.", "A slower response for query 'ca' arriving after 'cat' is ignored.", "The latest failed request does not let an earlier success overwrite its error state.", "async function latestResults(query, request, state) { const id = ++state.sequence; state.query = query; try { const data = await request(query); if (id !== state.sequence) return { stale: true }; state.data = data; state.error = null; return { stale: false, data }; } catch (error) { if (id !== state.sequence) return { stale: true }; state.error = error; throw error; } }", "Associate each request with a monotonically increasing identity before awaiting it.", "Apply either data or error only if the resolving request is still the most recent one."],
        ]
    },
    Modules: {
        hints: ["Keep each module's public surface explicit and avoid hidden import-time side effects.", "Use a dependency direction that does not create a cycle, and test both named exports and path resolution."],
        items: [
            ["Easy", "Split formatter exports", "Design a formatter module that exports named formatDate and formatCurrency functions, then show the corresponding named imports in a report module. Both functions should be independently importable without a default export.", "Importing formatCurrency from './formatters.js' produces a usable binding.", "A misspelled named export should fail module linking instead of silently returning undefined.", "export function formatDate(value) { return new Intl.DateTimeFormat('en').format(new Date(value)); }\nexport function formatCurrency(value) { return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(value); }\n// report.js: import { formatDate, formatCurrency } from './formatters.js';", "Use matching export and import names for the module's public API.", "Keep the formatter module independent of page rendering so another consumer can reuse it."],
            ["Easy", "Move constants out of a component module", "Create a constants module exporting a frozen SUPPORTED_TYPES array and import it into an upload validator. The validator should use the imported array without duplicating the list.", "The validator accepts a value found in SUPPORTED_TYPES.", "Attempting to mutate the exported array does not change the supported set.", "export const SUPPORTED_TYPES = Object.freeze(['pdf', 'txt', 'docx']);\n// validator.js: import { SUPPORTED_TYPES } from './constants.js';\nexport function isSupported(type) { return SUPPORTED_TYPES.includes(type); }", "Put shared constants in a leaf module that does not import the validator or UI.", "Freeze the array at its definition and import its single source of truth."],
            ["Medium", "Avoid a circular module dependency", "Refactor modules A and B where A imports a helper from B and B imports A's mutable state during initialization. Extract the shared pure helper into a third leaf module and describe the new dependency direction.", "A imports helper from shared; B imports helper from shared; shared imports neither.", "Module initialization no longer reads a partially initialized binding from the cycle.", "// shared.js\nexport function normalizeKey(value) { return String(value).trim().toLowerCase(); }\n// a.js and b.js each import { normalizeKey } from './shared.js';", "Draw the import graph first and move only the shared pure behavior to the leaf.", "Both consumers can depend on the leaf without depending on each other."],
            ["Medium", "Make module initialization side-effect free", "Refactor an analytics module that currently sends a tracking event at import time. Export an initializeAnalytics(client) function and ensure importing the module performs no network request.", "No tracking call happens until initializeAnalytics is invoked.", "Importing the module in a test does not require network mocks for an event that should not happen.", "export function initializeAnalytics(client) { return { track(name, payload) { return client.send(name, payload); } }; }", "Separate declaring a capability from invoking it.", "Inject the client at initialization and keep top-level module statements declarative."],
            ["Hard", "Define a stable public module facade", "Build a facade module that re-exports only parseResume and validateResume from internal files while keeping helper parsers private to their modules. Explain how this protects consumers from internal file rearrangement.", "Consumers import both supported functions from './resume/index.js'.", "An internal helper not re-exported is not part of the facade contract.", "export { parseResume } from './parseResume.js';\nexport { validateResume } from './validateResume.js';", "Treat the facade as the supported API and expose only operations consumers are allowed to depend on.", "Re-export explicit named bindings rather than forwarding every internal export."],
            ["Hard", "Load an optional browser feature dynamically", "Implement loadChartRenderer(featureEnabled) that dynamically imports './chartRenderer.js' only when enabled and returns null otherwise. Convert a missing-module rejection into a clear FeatureUnavailableError while preserving the original cause.", "Disabled feature performs no import and returns null.", "Enabled feature returns the module; a load failure rejects with named FeatureUnavailableError and cause.", "async function loadChartRenderer(featureEnabled) { if (!featureEnabled) return null; try { return await import('./chartRenderer.js'); } catch (cause) { const error = new Error('Chart renderer unavailable', { cause }); error.name = 'FeatureUnavailableError'; throw error; } }", "Put the dynamic import inside the enabled branch so disabled users do not load the chunk.", "Wrap only module-loading failure and retain its cause for diagnostics."],
        ]
    },
    "Error Handling": {
        hints: ["Validate at the boundary and throw errors that describe the violated contract without leaking secrets.", "Catch only errors you can handle; preserve original causes when translating an error for another layer."],
        items: [
            ["Easy", "Validate a required environment value", "Implement requireConfig(config, key) that returns a trimmed non-empty string or throws a ConfigError naming the missing key. Do not include the config object's values in the error.", "{API_HOST:' https://api.test '} returns the trimmed URL.", "A blank value throws ConfigError and its message contains the key but not other configuration values.", "function requireConfig(config, key) { const value = config?.[key]; if (typeof value !== 'string' || !value.trim()) { const error = new Error(`Missing required configuration: ${key}`); error.name = 'ConfigError'; throw error; } return value.trim(); }", "Check the requested key only and avoid serializing the entire config object into an error.", "Create a named error with a safe message, then return the normalized value."],
            ["Easy", "Return a fallback only for missing records", "Write getDisplayName(user) that returns a trimmed name or 'Guest' when the user or name is absent. If name exists but has the wrong type, throw a TypeError rather than hiding a data-integrity issue.", "{name:' Lee '} returns 'Lee'; null returns 'Guest'.", "{name:7} throws instead of displaying Guest.", "function getDisplayName(user) { if (user == null || user.name == null) return 'Guest'; if (typeof user.name !== 'string') throw new TypeError('User name must be text'); return user.name.trim() || 'Guest'; }", "Distinguish an absent optional value from a present value with an invalid type.", "Use fallback behavior only for the documented absence cases."],
            ["Medium", "Translate a storage failure safely", "Implement savePreference(storage, key, value) that JSON-serializes and writes the value. If serialization or storage throws, return {ok:false, error:'Unable to save preference'} without exposing the underlying message; otherwise return {ok:true}.", "A successful storage set returns {ok:true}.", "A circular value and a quota exception both return the same safe failure shape.", "function savePreference(storage, key, value) { try { storage.setItem(key, JSON.stringify(value)); return { ok: true }; } catch { return { ok: false, error: 'Unable to save preference' }; } }", "Both JSON serialization and storage can fail, so keep both operations inside the boundary.", "Return a stable user-safe error rather than copying the exception message into the UI."],
            ["Medium", "Preserve a cause while adding context", "Write loadRoadmap(load) that returns the loaded roadmap but wraps failures in RoadmapLoadError with message 'Unable to load roadmap' and the original error as cause. Do not lose the original stack or error identity in cause.", "A rejected network error becomes a RoadmapLoadError whose cause is that same error.", "A successful load returns the exact resolved value.", "async function loadRoadmap(load) { try { return await load(); } catch (cause) { const error = new Error('Unable to load roadmap', { cause }); error.name = 'RoadmapLoadError'; throw error; } }", "Catch only to add stable domain context, and retain the caught error as cause.", "Return the awaited successful value unchanged."],
            ["Hard", "Aggregate validation errors without partial writes", "Implement validateThenSave(input, validate, save) so validation returns a list of issues. If any issue exists, throw a ValidationError carrying all issues and never call save; otherwise call save once and return its result.", "Valid input calls save once and returns its value.", "Two validation issues are both preserved and save is never called.", "async function validateThenSave(input, validate, save) { const issues = validate(input); if (!Array.isArray(issues)) throw new TypeError('Validator must return an array'); if (issues.length) { const error = new Error('Input validation failed'); error.name = 'ValidationError'; error.issues = issues; throw error; } return save(input); }", "Complete validation before performing the side effect.", "Keep structured issues on the error so the caller can display field feedback without parsing a message."],
            ["Hard", "Retry only transient failures with a cap", "Design retryRead(read, attempts, isTransient) that retries a read operation only for errors approved by isTransient, never more than attempts calls, and rethrows the final original error. Invalid attempts are rejected before the first call.", "A transient first error followed by success returns the value.", "A non-transient first error calls read once and is rethrown unchanged.", "async function retryRead(read, attempts, isTransient) { if (!Number.isInteger(attempts) || attempts < 1) throw new RangeError('Invalid attempts'); for (let attempt = 1; attempt <= attempts; attempt += 1) { try { return await read(); } catch (error) { if (attempt === attempts || !isTransient(error)) throw error; } } }", "The retry policy should inspect the caught error and the remaining call budget.", "Throw the original error object when retry is not allowed or the budget is exhausted."],
        ]
    },
    "Local Storage": {
        hints: ["Browser storage contains strings and can fail; parse and validate data before trusting it.", "Version persisted shapes and handle missing, malformed, or stale values without claiming a save succeeded."],
        items: [
            ["Easy", "Persist a small theme preference", "Implement saveTheme(storage, theme) accepting only 'dark' or 'light'. Write the string under 'theme' and return true; return false for unsupported values without writing.", "saveTheme(storage,'dark') stores dark and returns true.", "'system' is rejected when it is not one of the supported preferences.", "function saveTheme(storage, theme) { if (!['dark', 'light'].includes(theme)) return false; storage.setItem('theme', theme); return true; }", "Validate the finite set before touching storage.", "Store the small scalar directly because localStorage values are already strings."],
            ["Easy", "Read a safe integer counter", "Write readCounter(storage, key) that returns a non-negative safe integer stored as decimal text, or 0 when missing or invalid. Reject strings with trailing characters rather than accepting parseInt's partial result.", "'12' returns 12; missing returns 0.", "'12items', '-1', and '1.5' return 0.", "function readCounter(storage, key) { const raw = storage.getItem(key); if (raw == null || !/^(0|[1-9]\\d*)$/.test(raw)) return 0; const value = Number(raw); return Number.isSafeInteger(value) ? value : 0; }", "Validate the complete string format before converting it.", "Number.isSafeInteger prevents very large decimal strings from becoming imprecise counts."],
            ["Medium", "Version a saved filter object", "Implement readFilters(storage) for a version-1 JSON value with role and location string fields. Return defaults when missing, malformed, wrong-version, or incorrectly typed; do not copy unknown fields into the result.", "A valid v1 record returns only role and location.", "A v2 record or JSON syntax error returns default empty strings.", "function readFilters(storage) { try { const value = JSON.parse(storage.getItem('job-filters') || 'null'); if (value?.version !== 1 || typeof value.role !== 'string' || typeof value.location !== 'string') return { role: '', location: '' }; return { role: value.role, location: value.location }; } catch { return { role: '', location: '' }; } }", "Parse inside a try block and validate the stored schema after parsing.", "Return a fresh allowlisted object so stale or unexpected keys are ignored."],
            ["Medium", "Make a storage write report failure honestly", "Write storeDraft(storage, draft) that serializes a draft and returns {saved:true} only after setItem succeeds. Catch serialization or quota/security failures and return {saved:false}; never retain a temporary object URL as if it were durable storage.", "A successful setItem returns saved:true.", "A quota error returns saved:false and does not claim persistence.", "function storeDraft(storage, draft) { try { const serialized = JSON.stringify(draft); storage.setItem('draft', serialized); return { saved: true }; } catch { return { saved: false }; } }", "The save result should reflect the actual storage operation, not merely successful serialization.", "Keep both serialization and setItem inside the failure boundary."],
            ["Hard", "Migrate a legacy saved-preference shape", "Implement readPreference(storage) supporting legacy boolean notificationsEnabled and current version-2 {notifications:{enabled:boolean}}. Return a normalized v2 object without writing during the read; invalid data falls back to enabled true.", "Legacy false becomes {version:2,notifications:{enabled:false}}.", "Malformed JSON and a string 'false' use the documented true fallback.", "function readPreference(storage) { try { const value = JSON.parse(storage.getItem('notification-preference') || 'null'); if (typeof value?.notificationsEnabled === 'boolean') return { version: 2, notifications: { enabled: value.notificationsEnabled } }; if (value?.version === 2 && typeof value.notifications?.enabled === 'boolean') return { version: 2, notifications: { enabled: value.notifications.enabled } }; } catch {} return { version: 2, notifications: { enabled: true } }; }", "Recognize only the known legacy and current schema, with strict boolean checks.", "Normalize in memory; keep migration writes in a separate explicit operation."],
            ["Hard", "Synchronize a storage update across tabs", "Implement listenForThemeChanges(window, onTheme) using the storage event. Notify only for the theme key and only for new values 'light' or 'dark'; return cleanup and do not fire for the current tab's own setItem call.", "A storage event for theme=dark calls onTheme('dark').", "Changes to unrelated keys and removal of the theme key do not notify.", "function listenForThemeChanges(windowObject, onTheme) { const handle = (event) => { if (event.key === 'theme' && ['light', 'dark'].includes(event.newValue)) onTheme(event.newValue); }; windowObject.addEventListener('storage', handle); return () => windowObject.removeEventListener('storage', handle); }", "The storage event is delivered to other documents in the same storage area.", "Filter by key and accepted value, then remove the same handler during cleanup."],
        ]
    },
};

const slug = (value) => value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

export const JAVASCRIPT_MORE_EXERCISES = Object.fromEntries(Object.entries(scenarios).map(([topic, data]) => [
    topic,
    data.items.map(([difficulty, title, problem, expected, edgeCase, solutionCode], index) => {
        const number = index + 1;
        const tests = [
            { name: "main behavior", input: problem, expected },
            { name: "boundary behavior", input: problem, expected: edgeCase }
        ];
        return {
            id: `js-${slug(topic)}-${difficulty.toLowerCase()}-${number}-v1`,
            title,
            career: "Full Stack Developer",
            phase: "JavaScript",
            topic,
            difficulty,
            estimatedTime: difficulty === "Easy" ? "20–30 minutes" : difficulty === "Medium" ? "35–50 minutes" : "50–75 minutes",
            kind: "coding",
            language: "JavaScript",
            problemStatement: `${problem} Provide the requested behavior, explain the key decision, and verify both the representative result and the stated boundary case.`,
            simplerProblem: `Implement the core behavior for the representative input before adding the stated validation and boundary behavior.`,
            requirements: [
                `Implement ${title.toLowerCase()} according to the input and output contract in the problem statement.`,
                `Keep the operation deterministic, handle the stated edge case, and do not mutate caller data unless explicitly required.`,
                `Add a short explanation of why the validation and branching order are correct.`
            ],
            examples: [
                { input: problem, output: expected, explanation: `This example checks the central ${topic} behavior and the exact output contract.` },
                { input: `Boundary case: ${edgeCase}`, output: edgeCase, explanation: `This case checks the boundary or invalid-input behavior required by the exercise.` }
            ],
            tests,
            hints: data.hints,
            conceptsToReview: [topic, "Input contracts", "Boundary testing"],
            learningObjectives: [
                `Apply ${topic} to the specific feature described by this exercise.`,
                `Explain the expected behavior for both the normal case and the stated boundary case.`,
                `Use the test cases to demonstrate correctness without changing the input unexpectedly.`
            ],
            prerequisites: ["JavaScript expressions", "Functions", "Basic debugging"],
            approach: `Treat the prompt as a contract: validate the accepted input shape, perform the ${topic}-specific operation, and return only the requested result. Check the representative example and boundary case independently so a happy-path implementation cannot conceal an input or state bug.`,
            walkthrough: `First identify the exact values that are accepted and the required output. Apply the operation shown in the example, then trace the boundary case through the same branches. The implementation below keeps that behavior in a focused function so each case can be tested independently.`,
            solutionCode,
            solutionLines: [
                `Validate the input contract before performing the ${topic} operation.`,
                `Apply the topic-specific transformation or decision while preserving the stated ordering and data rules.`,
                `Return the required value and check the representative and boundary examples.`
            ],
            commonMistakes: [
                `Assuming the input always has the ideal shape instead of handling the stated edge case.`,
                `Mutating a caller-owned array or object when the contract expects a new result.`,
                `Using truthiness where the exercise requires an exact type or boundary check.`
            ],
            followUp: `Extend ${title.toLowerCase()} with one additional valid input case while preserving the existing boundary behavior.`,
            completionCriteria: [
                `The implementation returns the expected result for the representative example.`,
                `The stated edge case is handled as required, with no hidden mutation or misleading success result.`,
                `The explanation connects the chosen ${topic} behavior to the tests.`
            ],
            starterCode: `function ${slug(title).replace(/-/g, "")}(input) {\n  // Implement the contract and boundary behavior described above.\n}`
        };
    })
]));
